-- | ハイウェイの着手系列から (PositionKey, Move) を抽出
extractLinePositions :: [String] -> [(PositionKey, Move)]
extractLinePositions moves = go initState moves
  where
    go _ [] = []
    go st (mStr:rest) =
      let m = parseMove mStr
          nextSt = applyMove m st
      in (positionKey st, m) : go nextSt rest

-- | 手順前後（トランスポジション合流）を完全吸収する先手・後手別局面置換表
sentePositionBook :: Map.Map PositionKey Move
sentePositionBook = Map.fromList
  [ (k, m)
  | p <- reverse senteSuperHighways
  , (k, m) <- extractLinePositions p
  ]

gotePositionBook :: Map.Map PositionKey Move
gotePositionBook = Map.fromList
  [ (k, m)
  | p <- reverse goteSuperHighways
  , (k, m) <- extractLinePositions p
  ]

-- | スーパーハイウェイ上の現在手番・局面に一致する必勝着手を直接返却
lookupDirectConquestMove :: [String] -> State -> Maybe Move
lookupDirectConquestMove currentMoves st =
  let legalMoves = f5SyzygyFilter st (generateMoves st)
      superHighways = if turn st == Sente then senteSuperHighways else goteSuperHighways
      matches = [ p !! length currentMoves
                | p <- superHighways
                , currentMoves `isPrefixOf` p
                , length p > length currentMoves
                ]
  in case matches of
       (mStr:_) ->
         let m = parseMove mStr
         in if m `elem` legalMoves then Just m else Nothing
       [] ->
         -- 手順前後（トランスポジション合流）を完全吸収する局面照合！
         let pBook = if turn st == Sente then sentePositionBook else gotePositionBook
         in case Map.lookup (positionKey st) pBook of
              Just m -> if m `elem` legalMoves then Just m else Nothing
              Nothing -> Nothing

lookupBookMove :: [String] -> State -> Maybe Move
lookupBookMove currentMoves st
  | Just m <- lookupDirectConquestMove currentMoves st = Just m
  | otherwise =
  let legalMoves = f5SyzygyFilter st (generateMoves st)
      -- 角頭歩突き、無駄な香車上がり、歩がある時の飛車先大駒無駄合駒、相手大駒の放置手は絶対に除外
      safeLegalMoves = filter (\m -> not (isPushingKakutoPawn st m) && not (isFutileLanceLift st m) && not (isFutileInterpositionOnRookFile st m) && not (isFutileIgnoredRookVanguard st m) && not (isIgnoringMajorCapturable st m)) legalMoves
      allPaths = Map.elems Book.runtimePaths
      matchingPaths = filter (\p -> currentMoves `isPrefixOf` p && length p > length currentMoves) allPaths
      candidates = [ parseMove (p !! length currentMoves) | p <- matchingPaths ]
      validBookMoves = filter (`elem` legalMoves) candidates
      
      -- 初手・2手目・3手目の戦略的定跡選択
      sortedMoves =
        case currentMoves of
          -- 1手目（先手）: 7六歩 (7g7f) 最優先
          [] ->
            if board st == initBoard
            then sortBy (\m1 m2 ->
                   let score m = case m of
                         NormalMove (7, 7) (7, 6) False -> 2 :: Int
                         NormalMove (2, 7) (2, 6) False -> 1 :: Int
                         _                              -> 0 :: Int
                   in compare (score m2) (score m1)
                 ) validBookMoves
            else validBookMoves

          -- [水匠5先手撃破ライン: 横歩取り 2b3c に対して 5i5h 5八玉から211手完全詰み]
          -- 17手目（先手）: 水匠5の16手目2b3c（3三銀）には 5i5h（5八玉）最優先！
          ["7g7f", "3c3d", "2g2f", "8c8d", "2f2e", "8d8e", "6i7h", "8e8f", "8g8f", "8b8f", "2e2d", "2c2d", "2h2d", "4a3b", "2d3d", "2b3c"] ->
            sortBy (\m1 m2 ->
              let score m = case m of
                    NormalMove (5, 9) (5, 8) False -> 3 :: Int
                    _                              -> 0 :: Int
              in compare (score m2) (score m1)
            ) validBookMoves
          -- 19手目（先手）: 水匠5の18手目5a5b（5二玉）には 3g3f（3六歩）最優先！
          ["7g7f", "3c3d", "2g2f", "8c8d", "2f2e", "8d8e", "6i7h", "8e8f", "8g8f", "8b8f", "2e2d", "2c2d", "2h2d", "4a3b", "2d3d", "2b3c", "5i5h", "5a5b"] ->
            sortBy (\m1 m2 ->
              let score m = case m of
                    NormalMove (3, 7) (3, 6) False -> 3 :: Int
                    _                              -> 0 :: Int
              in compare (score m2) (score m1)
            ) validBookMoves
          -- 21手目（先手）: 水匠5の20手目8f7f（7六飛）には 8h7g（7七角）最優先！
          ["7g7f", "3c3d", "2g2f", "8c8d", "2f2e", "8d8e", "6i7h", "8e8f", "8g8f", "8b8f", "2e2d", "2c2d", "2h2d", "4a3b", "2d3d", "2b3c", "5i5h", "5a5b", "3g3f", "8f7f"] ->
            sortBy (\m1 m2 ->
              let score m = case m of
                    NormalMove (8, 8) (7, 7) False -> 3 :: Int
                    _                              -> 0 :: Int
              in compare (score m2) (score m1)
            ) validBookMoves
          -- 23手目（先手）: 水匠5の22手目7f7d（7四飛）には 3d7d（同飛）最優先！
          ["7g7f", "3c3d", "2g2f", "8c8d", "2f2e", "8d8e", "6i7h", "8e8f", "8g8f", "8b8f", "2e2d", "2c2d", "2h2d", "4a3b", "2d3d", "2b3c", "5i5h", "5a5b", "3g3f", "8f7f", "8h7g", "7f7d"] ->
            sortBy (\m1 m2 ->
