-- | 玉の周囲の脱出可能マストポロジー（Escape Topology）
-- 盤外、受手側の守備駒の壁、攻め手の利きによって塞がれていない、玉が合法的に逃げられる隣接マス
getKingEscapes :: Player -> Square -> Board -> [Square]
getKingEscapes kingPlayer (kx, ky) bd =
  let opp = opponent kingPlayer
      neighbors = [ (kx + dx, ky + dy)
                  | dx <- [-1..1], dy <- [-1..1], (dx, dy) /= (0, 0)
                  , not (isOutOfBounds (kx + dx, ky + dy))
                  ]
      canEscapeTo sq = case Map.lookup sq bd of
        Just (Piece p _) | p == kingPlayer -> False -- 味方の壁で塞がれている
        _ -> not (isSquareUnderAttack opp sq bd)    -- 相手の利きがなければ逃げられる
  in filter canEscapeTo neighbors

-- | 普遍商空間エンドゲームテーブルベース (Universal Quotient EGTB)
-- 玉がどこにいようと（美濃囲い、矢倉、穴熊、中住まい、端玉、中段玉）、
-- 玉の周囲の脱出可能トポロジーを法とする商空間同値類として一元的に即詰みを判定！
lookupUniversalQuotientEGTB :: State -> Maybe (Int, Move)
lookupUniversalQuotientEGTB st =
  let att = turn st
      def = opponent att
      bd = board st
      curHands = hands st
      maybeDefK = findKing def bd
  in case maybeDefK of
       Nothing -> Nothing
       Just kSq@(kx, ky) ->
         let escapes = getKingEscapes def kSq bd
             myHands = fromMaybe emptyHand (Map.lookup att curHands)
             hasGold = Map.findWithDefault 0 Gold myHands >= 1
             hasKnight = Map.findWithDefault 0 Knight myHands >= 1
             
             -- 1. 普遍的金打ちイデアル（頭金・腹金・尻金・押し込みのトポロジー商空間同値類: DTM = 1）
             -- 玉の隣接マスで、支え（紐）があり、打った金が玉に王手をかけ、
             -- かつ玉のすべての脱出マス（escapes）をカバーするマスを探す
             goldDropMate = if not hasGold then Nothing else
               let candidateSquares = [ (kx + dx, ky + dy)
                                      | dx <- [-1..1], dy <- [-1..1], (dx, dy) /= (0, 0)
                                      , not (isOutOfBounds (kx + dx, ky + dy))
                                      , not (Map.member (kx + dx, ky + dy) bd)
                                      , isSquareUnderAttack att (kx + dx, ky + dy) bd -- 支え（紐）あり
                                      ]
                   isMateDrop sq =
                     let dropMv = DropMove Gold sq
                         nextSt = applyMove dropMv st
                         nextBd = board nextSt
                         isCheck = isKingUnderAttack def nextBd
                         remainingEscapes = [ e | e <- escapes, e /= sq
                                                , not (canPieceReachTarget sq (Piece att Gold) e nextBd) ]
                     in isCheck && null remainingEscapes
               in case filter isMateDrop candidateSquares of
                    (mSq:_) -> Just (1, DropMove Gold mSq)
                    []      -> Nothing
             
             -- 2. 盤上の龍・馬・金・成駒による普遍的突入詰み（DTM = 1）
             boardPieceMate =
               let myBoardAttackers = [ (sq, p) | (sq, p@(Piece pPlr pt)) <- Map.toList bd
                                                , pPlr == att
                                                , pt `elem` [PRook, PBishop, Gold, PPawn, PSilver, PKnight, PLance] ]
                   candidateMoves =
                     [ NormalMove fromSq toSq False
                     | (fromSq, piece@(Piece _ pType)) <- myBoardAttackers
                     , dx <- [-1..1], dy <- [-1..1], (dx, dy) /= (0, 0)
                     , let toSq = (kx + dx, ky + dy)
                     , not (isOutOfBounds toSq)
                     , canPieceReachTarget fromSq piece toSq bd
                     , isSquareUnderAttack att toSq bd || pType `elem` [PRook, PBishop]
                     ]
                   isMateMove mv =
                     let nextSt = applyMove mv st
                         nextBd = board nextSt
                         isCheck = isKingUnderAttack def nextBd
                         (NormalMove _ toSq _) = mv
                         remainingEscapes = [ e | e <- escapes, e /= toSq
                                                , not (isSquareUnderAttack att e nextBd) ]
                     in isCheck && null remainingEscapes
               in case filter isMateMove candidateMoves of
                    (mv:_) -> Just (1, mv)
                    []     -> Nothing
             
             -- 3. 普遍的吊るし桂イデアル（DTM = 1）
             tsurushiKeiMate = if not hasKnight || not (null escapes) then Nothing else
               let dirY = if att == Sente then 2 else -2
                   dropSquares = [ (kx - 1, ky + dirY), (kx + 1, ky + dirY) ]
                   validSq sq = not (isOutOfBounds sq) && not (Map.member sq bd)
               in case filter validSq dropSquares of
                    (sq:_) -> Just (1, DropMove Knight sq)
                    []     -> Nothing
         in listToMaybe [ res | Just res <- [goldDropMate, boardPieceMate, tsurushiKeiMate] ]

-- | 商空間エンドゲームテーブル (QEGTB) 照合
-- ★ 玉形の違いを幾何学的脱出トポロジーの商空間同値類として一元的に判定する Universal QEGTB を最優先照会！
lookupQuotientTablebase :: State -> Maybe (Int, Move)
lookupQuotientTablebase st =
  case lookupUniversalQuotientEGTB st of
    Just uRes -> Just uRes
    Nothing ->
      let att = turn st
          def = opponent att
          curBd = board st
          curHands = hands st
          maybeDefKingSq = findKing def curBd
      in case maybeDefKingSq of
       Nothing -> Nothing
       Just kSq ->
         let myHands = fromMaybe emptyHand (Map.lookup att curHands)
             hasRequiredHand reqs = all (\(pt, cnt) -> Map.findWithDefault 0 pt myHands >= cnt) reqs

             matchPattern QuotientPattern{..} =
               if not (qpTargetKingRank kSq)
               then Nothing
               else if not (hasRequiredHand qpRequiredHand)
               then Nothing
               else if not (qpSupportCheck kSq curBd att)
               then Nothing
               else
                 case qpCandidateMove kSq att curBd of
                   Just mv ->
                     -- 着手後の局面で実際に相手玉が王手になっているか安全検証
                     let nextSt = applyMove mv st
                     in if isKingUnderAttack def (board nextSt)
                        then Just (qpDTM, mv)
                        else Nothing
                   Nothing -> Nothing

             matches = [ res | pat <- endgameTablebase, Just res <- [matchPattern pat] ]
         in listToMaybe matches

-- | USI の go コマンド引数から思考時間上限（マイクロ秒）を計算
-- byoyomi (秒読み) の秒数を上限とし、通信・I/Oラグ（150ms）を差し引いて切れ負けを完全防止
-- | 指し手を指した結果の局面が、QEGTB（商空間エンドゲームテーブル）の配置空間と同値であるか判定・評価
-- 1. 指した後の局面で自分手番と仮定した場合にQEGTB即詰み（DTM 1 または 3）になる手（詰めろ・QEGTB直接誘導）
-- 2. 相手玉の脱出可能トポロジー（Escape Topology）を縮約し、頭金・腹金・吊るし桂の前提空間へと収束させる手
-- 3. 相手玉の隣接マスに味方の紐（支え）を新設してQEGTBイデアルを構築する手
evalQuotientEquivalence :: State -> Move -> Double
evalQuotientEquivalence st m =
  let plr = turn st
      opp = opponent plr
      curBd = board st
      nextSt = applyMove m st
      nextBd = board nextSt
      
      -- 1. 指し手を指した後の局面で、自分が手番なら即座にQEGTB即詰み（DTM 1 または 3）になるか（詰めろ・QEGTB同値空間への直接突入）
      stHypotheticalMyTurn = nextSt { turn = plr }
      qegtbDirectHitScore = case lookupQuotientTablebase stHypotheticalMyTurn of
        Just (dtm, _) ->
          -- DTM 1（頭金・腹金・吊るし桂等の即詰み同値空間に遷移）なら超特大ボーナス！
          if dtm == 1 then 1800.0 else 1200.0
        Nothing       -> 0.0
      
      -- 2. 相手玉の脱出トポロジー（Escape Topology）の縮約度
      escapeReductionScore =
        case (findKing opp curBd, findKing opp nextBd) of
          (Just kCur, Just kNext) ->
            let curEscapes = length (getKingEscapes opp kCur curBd)
                nextEscapes = length (getKingEscapes opp kNext nextBd)
                -- 脱出可能マスが0（完全包囲・退路なし）になった場合
                zeroEscapeBonus = if nextEscapes == 0 then 600.0 else 0.0
                -- 脱出可能マスを狭めた（トポロジー縮約）ボーナス
                reducedBonus = if nextEscapes < curEscapes
                               then fromIntegral (curEscapes - nextEscapes) * 220.0
                               else 0.0
            in zeroEscapeBonus + reducedBonus
          _ -> 0.0
      
      -- 3. QEGTBイデアル構築（相手玉の隣接マスへの支え・紐の創出、頭金・腹金スペースの確保）
      idealSupportScore =
        case findKing opp nextBd of
          Just (kx, ky) ->
            let neighbors = [ (kx + dx, ky + dy)
                            | dx <- [-1..1], dy <- [-1..1], (dx, dy) /= (0, 0)
                            , not (isOutOfBounds (kx + dx, ky + dy))
                            ]
                -- 着手後に新たに味方の支え（紐）がついた隣接マスの数
                newSupportedNeighbors = length [ sq | sq <- neighbors
                                                    , isSquareUnderAttack plr sq nextBd
                                                    , not (isSquareUnderAttack plr sq curBd) ]
            in fromIntegral newSupportedNeighbors * 150.0
          Nothing -> 0.0
  in qegtbDirectHitScore + escapeReductionScore + idealSupportScore

-- | 自玉周りの指し手の選択において、駒の配置空間が相手のQEGTB（商空間エンドゲームテーブル）にない局面になる手を優先
-- 1. 自玉自身の移動、自玉から2マス以内への移動・駒打ち、自玉王手回避手など「自玉周りの手」を判定
-- 2. 指した後の局面 nextSt で相手視点から見て自玉がQEGTB即詰み・詰めろ同値類に該当する場合（自爆手）は特大ペナルティ（-8000.0）
-- 3. 相手視点から見て自玉がQEGTBに存在しない（配置空間がQEGTBにない安全空間）局面になる手には特大優先ボーナス（+850.0）
-- 4. 自玉脱出路の確保度、周囲の相手の利きの排除、自陣の紐・守備駒の配置度を加算評価
evalAntiQuotientSafety :: State -> Move -> Double
evalAntiQuotientSafety st m =
  let plr = turn st
      opp = opponent plr
      curBd = board st
      nextSt = applyMove m st
      nextBd = board nextSt
      
      curKingSq = findKing plr curBd
      nextKingSq = findKing plr nextBd
      
      isKingMove = case m of
        NormalMove f _ _ -> case Map.lookup f curBd of
                              Just (Piece p King) -> p == plr
                              _                   -> False
        _                -> False
        
      toSq = case m of
        NormalMove _ t _ -> t
        DropMove _ t     -> t
        
      isNearKing = case curKingSq of
        Just (kx, ky) -> max (abs (fst toSq - kx)) (abs (snd toSq - ky)) <= 2
        Nothing       -> False
        
      isUnderCheck = isKingUnderAttack plr curBd
      isSelfKingRelated = isKingMove || isNearKing || isUnderCheck
      
  in if not isSelfKingRelated
     then 0.0
     else
       -- 指した後の局面で、相手手番から見て相手が自玉をQEGTBで即詰み・詰めろにできるか照合
       case lookupQuotientTablebase nextSt of
         -- 相手視点のQEGTBに該当してしまう（自ら相手のQEGTB詰み網に飛び込む悪手！）
         Just (dtm, _) ->
           if dtm == 1 then -8000.0 else -4000.0
         -- 相手視点のQEGTBに存在しない（配置空間がQEGTBにない安全空間！）
         Nothing ->
           let -- 自玉の脱出トポロジー（逃げ道）の広さ
               escapesBonus = case nextKingSq of
                 Just nkSq ->
                   let escapes = length (getKingEscapes plr nkSq nextBd)
                   in fromIntegral escapes * 160.0
                 Nothing -> 0.0
               
               -- 自玉周り（隣接8マス）における相手の利きの少なさ（脅威の排除）
               threatReductionBonus = case nextKingSq of
                 Just (nkx, nky) ->
                   let neighbors = [ (nkx + dx, nky + dy)
                                   | dx <- [-1..1], dy <- [-1..1], (dx, dy) /= (0, 0)
                                   , not (isOutOfBounds (nkx + dx, nky + dy))
                                   ]
                       oppThreats = length [ sq | sq <- neighbors, isSquareUnderAttack opp sq nextBd ]
                   in if oppThreats == 0 then 400.0 else fromIntegral (max 0 (8 - oppThreats)) * 40.0
                 Nothing -> 0.0
               
               -- 自玉周り（隣接8マス）における味方の利き（守備・紐）の厚み
               friendlySupportBonus = case nextKingSq of
                 Just (nkx, nky) ->
                   let neighbors = [ (nkx + dx, nky + dy)
                                   | dx <- [-1..1], dy <- [-1..1], (dx, dy) /= (0, 0)
                                   , not (isOutOfBounds (nkx + dx, nky + dy))
                                   ]
                       friendlyGuards = length [ sq | sq <- neighbors, isSquareUnderAttack plr sq nextBd ]
                   in fromIntegral friendlyGuards * 50.0
                 Nothing -> 0.0
               
               -- 「配置空間がQEGTBにない」安全空間確保の基本ボーナス！
               safeNonQegtbBonus = 850.0
           in safeNonQegtbBonus + escapesBonus + threatReductionBonus + friendlySupportBonus

-- | 飛車・金（および全駒）の目的のない往復移動（Shuffling / Ping-pong）、
--   千日手未遂（2回目・3回目の同一局面）、彷徨い移動（うろうろ手損）の検知とペナルティ
-- | 攻め駒（飛・角・銀・桂・竜・馬）が相手の駒に包囲・詰まされている（Trapped）かどうかの判定
isTrappedPiece :: Square -> PieceType -> Player -> Board -> Bool
isTrappedPiece sq pt plr bd =
  let opp = opponent plr
      oppAttackers = getPiecesCovering opp sq bd
  in if null oppAttackers
     then False -- 当たりになっていなければ詰まされていない
     else
       let candidateDests = [ dest | dest <- Map.keys bd ++ [ (x, y) | x <- [1..9], y <- [1..9] ]
                                   , canPieceReachTarget sq (Piece plr pt) dest bd
                                   , case Map.lookup dest bd of
                                       Just (Piece p _) -> p /= plr
                                       Nothing          -> True
                            ]
           isSafeSquare dest =
             let oppAtk = getPiecesCovering opp dest bd
                 myDef  = getPiecesCovering plr dest bd
                 hasCheap = any (\(_, Piece _ opt) -> opt `elem` [Pawn, Lance, Knight, Silver]) oppAtk
             in null oppAtk || (length myDef > length oppAtk && not hasCheap)
           
           hasSafeRetreat = any isSafeSquare candidateDests
       in not hasSafeRetreat -- 安全な退避先が1つもなければ「詰まされている（Trapped）」！

-- | 攻め駒が詰まされた場合のモース勾配流（Desperado 流）
-- 価値の低い駒交換（歩や香との刺し違え・タダ死に）を厳罰排除し、
-- 最大価値の駒（金・銀・角・飛）との刺し違え、または急所破壊・王手を最優先化
evalTrappedPieceDesperado :: State -> Move -> Double
evalTrappedPieceDesperado st m =
  let plr = turn st
      opp = opponent plr
      bd = board st
      nextSt = applyMove m st
      nextBd = board nextSt
      isCheck = isKingUnderAttack opp nextBd
  in case m of
       NormalMove from to _ ->
         case Map.lookup from bd of
           Just (Piece p pt) | p == plr && pt `elem` [Rook, PRook, Bishop, PBishop, Silver, PSilver, Knight] ->
             let isTrapped = isTrappedPiece from pt plr bd
             in if not isTrapped
                then 0.0
                else
                  let targetCap = Map.lookup to bd
                  in case targetCap of
                       -- 1. 相手の駒を取る手（刺し違え）
                       Just (Piece _ capPt) ->
                         let capVal = pieceValue capPt
                         in if capVal >= 500.0
                            then 3200.0 + capVal * 4.0 -- 金・銀・角・飛との最大刺し違え（大成功の Desperado！）
                            else if capVal >= 300.0
                            then (if pt `elem` [Rook, Bishop] then -2500.0 else 600.0) -- 桂・香との刺し違え
                            else
                              -- ★ 歩との刺し違え（最悪の低価値駒交換！角歩交換・銀歩交換・飛車歩交換）
                              if pt `elem` [Rook, PRook, Bishop, PBishop]
                              then -9000.0 -- 大駒で歩を取って死ぬのは絶対禁止！
                              else if pt `elem` [Silver, PSilver]
                              then -6000.0 -- 銀で歩を取って死ぬのも絶対禁止！
                              else -3500.0 -- 桂で歩を取って死ぬのも禁止！
                       -- 2. 駒を取らずに逃げる手
                       Nothing ->
                         let oppAtkOnTo = getPiecesCovering opp to nextBd
                             myDefOnTo  = getPiecesCovering plr to nextBd
                             isStillDead = not (null oppAtkOnTo) && (null myDefOnTo || any (\(_, Piece _ opt) -> opt == Pawn) oppAtkOnTo)
                         in if isCheck
                            then 800.0 -- 王手で陣形を崩す手筋
                            else if isStillDead
                            then -7500.0 -- 駒も取れずに結局歩などにタダ取られする無駄な逃げ
                            else 0.0
           _ -> 0.0
       DropMove _ _ -> 0.0

-- | 角打ちの手（DropMove Bishop to）の品質・角道の開通度（Mobility）評価
-- 98角のように角道が自駒で塞がれている無意味な死に角打ちを完全排除
evalBishopDropQuality :: State -> Move -> Double
evalBishopDropQuality st m =
  let plr = turn st
      opp = opponent plr
      curBd = board st
      nextSt = applyMove m st
      nextBd = board nextSt
  in case m of
       DropMove Bishop to ->
         let dirs = [(-1, -1), (-1, 1), (1, -1), (1, 1)]
             countRay (dx, dy) =
               let raySquares = takeWhile (\(x, y) -> x >= 1 && x <= 9 && y >= 1 && y <= 9)
                                          [ (fst to + i * dx, snd to + i * dy) | i <- [1..8] ]
                   validSquares [] = 0
                   validSquares (sq:sqs) =
                     case Map.lookup sq curBd of
                       Nothing -> 1 + validSquares sqs
                       Just _  -> 1
               in validSquares raySquares
             
             totalMobility = sum (map countRay dirs)
             
             oppKingSq = findKing opp nextBd
             hasDirectRayToKing = case oppKingSq of
               Just kSq -> canPieceReachTarget to (Piece plr Bishop) kSq nextBd
               Nothing  -> False
               
             inEnemyZone y = if plr == Sente then y <= 3 else y >= 7
             attacksEnemyCamp = any (\(dx, dy) ->
               let targetSquares = [ (fst to + i * dx, snd to + i * dy) | i <- [1..8] ]
               in any (\sq -> not (isOutOfBounds sq) && inEnemyZone (snd sq)) targetSquares
               ) dirs
         in if totalMobility <= 2
            then -10000.0 -- 角道が0〜2マスしか通っていない！98角などの完全な死角打ちは厳禁！
            else if totalMobility <= 4 && not hasDirectRayToKing
            then -4000.0  -- 角道が狭すぎる無意味な角打ち
            else if hasDirectRayToKing
            then 800.0    -- 敵玉に直通する急所角打ち！
            else if attacksEnemyCamp
            then 400.0    -- 相手陣を睨む有効な角打ち
            else 100.0
       _ -> 0.0

-- | 相手の角打ち（Bishop Drop Threat）に対する脆弱性・無防備さの評価
-- 相手が手持ちに角を持っているとき、自陣・中段への危険な角打ち（両取り・馬作り・王手）をスキャンして厳罰化
evalBishopDropVulnerability :: Player -> State -> Double
evalBishopDropVulnerability plr st =
  let opp = opponent plr
      oppHand = Map.findWithDefault Map.empty opp (hands st)
      hasOppBishop = Map.findWithDefault 0 Bishop oppHand > 0
  in if not hasOppBishop
     then 0.0
     else
       let bd = board st
           targetY = if plr == Sente then [4..9] else [1..6]
           candidateDropSquares = [ (x, y) | x <- [1..9], y <- targetY, not (Map.member (x, y) bd) ]
           
           isDangerousBishopDrop sq =
             let myDefenders = getPiecesCovering plr sq bd
                 isProtected = not (null myDefenders)
                 
                 testBd = Map.insert sq (Piece opp Bishop) bd
                 threatenedPieces = [ tsq | (tsq, Piece p pt) <- Map.toList testBd
                                          , p == plr
                                          , pt `elem` [King, Rook, PRook, Gold, Silver]
                                          , canPieceReachTarget sq (Piece opp Bishop) tsq testBd ]
                 
                 isForkOrCheck = length threatenedPieces >= 2 ||
                                 any (\tsq -> Map.lookup tsq bd == Just (Piece plr King)) threatenedPieces
                 
                 canPromoteNext = if opp == Sente then snd sq >= 7 else snd sq <= 3
             in not isProtected && (isForkOrCheck || canPromoteNext)
             
           dangerousCount = length (filter isDangerousBishopDrop candidateDropSquares)
       in if dangerousCount > 0
          then - (fromIntegral dangerousCount * 1200.0) -- 危険な角打ちの隙1箇所につき -1200点！
          else 600.0 -- 隙がゼロなら完璧な鉄壁防御ボーナス！

-- | 銀の前線進出（棒銀・腰掛け銀・早繰り銀）および石田流本組のモース勾配流
-- 飛車の無駄なうろうろ手損を排し、力強い銀の前線進出と石田流の理想布陣を網羅
-- | 銀の前線進出（棒銀・腰掛け銀・早繰り銀）および石田流本組の局面評価（モース勾配流）
-- 局面の静的評価に直接反映することで、飛車のうろうろ手損を完全排除し、
-- 銀の前線繰り出しと石田流本組の空中要塞構築を確実に選択させる
evalSilverAdvanceAndIshidaFormation :: Player -> State -> Double
evalSilverAdvanceAndIshidaFormation p st =
  let bd = board st
      -- 1. 銀の前進・前線配置（棒銀・腰掛け銀・早繰り銀・中央厚み）
      silvers = [ sq | (sq, Piece owner pt) <- Map.toList bd, owner == p, pt `elem` [Silver, PSilver] ]
      silverScore = sum
        [ let (x, y) = sq
              adv = if p == Sente then 9 - y else y - 1
              -- 棒銀 (Climbing Silver: 先手2筋・1筋, 後手8筋・9筋)
              isClimbing = if p == Sente
                           then (x == 2 || x == 1 || (x == 3 && y == 7)) && y <= 7
                           else (x == 8 || x == 9 || (x == 7 && y == 3)) && y >= 3
              -- 腰掛け銀・中央厚み (Reclining / Central: 4,5,6筋の中段)
              isCentral = if p == Sente
                          then sq `elem` [(5, 6), (4, 6), (6, 6), (5, 5), (4, 5)]
                          else sq `elem` [(5, 4), (6, 4), (4, 4), (5, 5), (6, 5)]
              -- 前線進出 (Frontline: 5段目以上)
              isFront = if p == Sente then y <= 5 else y >= 5
          in (if isClimbing then 1800.0 else 0.0) +
             (if isCentral  then 1600.0 else 0.0) +
             (if isFront    then 1200.0 else (if adv >= 2 then fromIntegral adv * 250.0 else 0.0))
        | sq <- silvers
        ]
      
      -- 2. 石田流本組・三間飛車のモース勾配流（浮き飛車・7五歩・7七桂・9七角）
      ishidaScore =
        if p == Sente
        then
          let hasSente75P = Map.lookup (7, 5) bd == Just (Piece Sente Pawn)
              hasSente76R = Map.lookup (7, 6) bd == Just (Piece Sente Rook)
              hasSente78R = Map.lookup (7, 8) bd == Just (Piece Sente Rook)
              hasSente77N = Map.lookup (7, 7) bd == Just (Piece Sente Knight)
              hasSente97B = Map.lookup (9, 7) bd == Just (Piece Sente Bishop)
              
              sankanBonus   = if hasSente78R then (if hasSente75P then 2200.0 else 900.0) else 0.0
              pawnBonus     = if hasSente75P then 800.0 else 0.0
              floatingBonus = if hasSente76R && hasSente75P then 3400.0 else 0.0
              knightBonus   = if hasSente77N && hasSente76R then 1200.0 else 0.0
              bishopBonus   = if hasSente97B && hasSente77N then 900.0 else 0.0
          in sankanBonus + pawnBonus + floatingBonus + knightBonus + bishopBonus
        else
          let hasGote35P = Map.lookup (3, 5) bd == Just (Piece Gote Pawn)
              hasGote34R = Map.lookup (3, 4) bd == Just (Piece Gote Rook)
              hasGote32R = Map.lookup (3, 2) bd == Just (Piece Gote Rook)
              hasGote33N = Map.lookup (3, 3) bd == Just (Piece Gote Knight)
              hasGote13B = Map.lookup (1, 3) bd == Just (Piece Gote Bishop)
              
              sankanBonus   = if hasGote32R then (if hasGote35P then 2200.0 else 900.0) else 0.0
              pawnBonus     = if hasGote35P then 800.0 else 0.0
              floatingBonus = if hasGote34R && hasGote35P then 3400.0 else 0.0
              knightBonus   = if hasGote33N && hasGote34R then 1200.0 else 0.0
              bishopBonus   = if hasGote13B && hasGote33N then 900.0 else 0.0
          in sankanBonus + pawnBonus + floatingBonus + knightBonus + bishopBonus

      -- 3. 飛車のうろうろ手損（自陣での無駄な筋変更・横移動・目的のない浮き）への厳罰
      rooks = [ sq | (sq, Piece owner pt) <- Map.toList bd, owner == p, pt == Rook ]
      wanderingRookPenalty = sum
        [ let (rx, ry) = sq
              isIshidaLegit = if p == Sente
                              then (sq == (7, 8) || (sq == (7, 6) && Map.lookup (7, 5) bd == Just (Piece Sente Pawn)))
                              else (sq == (3, 2) || (sq == (3, 4) && Map.lookup (3, 5) bd == Just (Piece Gote Pawn)))
              isOriginalPos = if p == Sente then sq == (2, 8) else sq == (8, 2)
              isLegitFuribisha = if p == Sente then rx `elem` [5, 6, 7, 8] && ry == 8
                                 else rx `elem` [2, 3, 4, 5] && ry == 2
              -- 飛車先が歩で塞がれているのに浮いている手損 (2七飛、2六飛等)
              pawnAhead = if p == Sente then Map.lookup (rx, 7) bd == Just (Piece p Pawn)
                          else Map.lookup (rx, 3) bd == Just (Piece p Pawn)
              isAimlessLift = if p == Sente
                              then (ry == 7 || ry == 6) && pawnAhead && not isIshidaLegit
                              else (ry == 3 || ry == 4) && pawnAhead && not isIshidaLegit
              -- 無意味な筋変更 (3筋や4筋など歩も突いていないのに自陣に横移動)
              isAimlessFile = if p == Sente
                              then not isOriginalPos && not isLegitFuribisha && not isIshidaLegit && ry >= 7
                              else not isOriginalPos && not isLegitFuribisha && not isIshidaLegit && ry <= 3
          in (if isAimlessLift then -3500.0 else 0.0) +
             (if isAimlessFile then -4000.0 else 0.0)
        | sq <- rooks
        ]
  in silverScore + ishidaScore + wanderingRookPenalty


evalSilverAdvanceAndIshidaFlow :: State -> Move -> Double
evalSilverAdvanceAndIshidaFlow st m =
  let plr = turn st
      opp = opponent plr
      curBd = board st
      nextSt = applyMove m st
      nextBd = board nextSt
  in case m of
       NormalMove from to _ ->
         case Map.lookup from curBd of
           -- A. 銀の前進・前線進出（棒銀・腰掛け銀・早繰り銀）
           Just (Piece p Silver) | p == plr ->
             let (fx, fy) = from
                 (tx, ty) = to
                 isAdvancing = if plr == Sente then ty < fy else ty > fy
                 -- 1. 棒銀（Climbing Silver: 先手2筋・後手8筋を登る）
                 isClimbingSilver =
                   if plr == Sente
                   then (fx `elem` [1, 2, 3] && tx `elem` [1, 2, 3] && ty <= 7)
                   else (fx `elem` [7, 8, 9] && tx `elem` [7, 8, 9] && ty >= 3)
                 -- 2. 腰掛け銀・中央進出（Reclining / Central Silver: 5六・4六・6六）
                 isCentralSilver =
                   if plr == Sente
                   then (to == (5, 6) || to == (4, 6) || to == (6, 6) || to == (5, 5) || to == (4, 5))
                   else (to == (5, 4) || to == (6, 4) || to == (4, 4) || to == (5, 5) || to == (6, 5))
                 -- 3. 前線（敵陣近傍）進出
                 isFrontline = if plr == Sente then ty <= 5 else ty >= 5
             in if not isAdvancing then 0.0
                else if isClimbingSilver then 1800.0 -- 棒銀の力強い進出！
                else if isCentralSilver  then 1600.0 -- 腰掛け銀・中央厚み進出！
                else if isFrontline      then 1200.0 -- 前線進出！
                else 600.0
           
           -- B. 石田流本組・三間飛車のモース勾配流
           -- 1. 飛車の動き（三間飛車 7八飛 / 3二飛、浮き飛車 7六飛 / 3四飛）
           Just (Piece p Rook) | p == plr ->
             let (fx, fy) = from
                 (tx, ty) = to
                 -- 先手石田流
                 isSenteSankanRook = plr == Sente && to == (7, 8)
                 isSenteFloatingRook = plr == Sente && from == (7, 8) && to == (7, 6) &&
                                       Map.lookup (7, 5) curBd == Just (Piece Sente Pawn)
                 -- 後手石田流
                 isGoteSankanRook = plr == Gote && to == (3, 2)
                 isGoteFloatingRook = plr == Gote && from == (3, 2) && to == (3, 4) &&
                                      Map.lookup (3, 5) curBd == Just (Piece Gote Pawn)
             in if isSenteFloatingRook || isGoteFloatingRook
                then 3400.0 -- ★ 石田流浮き飛車（最強の空中戦要塞！）
                else if isSenteSankanRook || isGoteSankanRook
                then (if Map.lookup (if plr == Sente then (7, 5) else (3, 5)) curBd == Just (Piece plr Pawn) then 2200.0 else 1000.0)
                else 0.0
           
           -- 2. 歩の動き（石田流の命：7五歩 / 3五歩突き）
           Just (Piece p Pawn) | p == plr ->
             let isSenteIshidaPawn = plr == Sente && from == (7, 6) && to == (7, 5)
                 isGoteIshidaPawn  = plr == Gote && from == (3, 4) && to == (3, 5)
             in if isSenteIshidaPawn || isGoteIshidaPawn
                then 1200.0 -- ★ 石田流の急所歩突き！
                else 0.0
                
           -- 3. 桂馬の動き（石田流本組の桂跳ね：7七桂 / 3三桂）
           Just (Piece p Knight) | p == plr ->
             let isSenteIshidaKnight = plr == Sente && to == (7, 7) &&
                                       Map.lookup (7, 6) curBd == Just (Piece Sente Rook)
                 isGoteIshidaKnight  = plr == Gote && to == (3, 3) &&
                                       Map.lookup (3, 4) curBd == Just (Piece Gote Rook)
             in if isSenteIshidaKnight || isGoteIshidaKnight
                then 1200.0 -- ★ 石田流本組の桂跳ね！
                else 0.0
                
           -- 4. 角の動き（石田流の角転回：9七角 / 1三角）
           Just (Piece p Bishop) | p == plr ->
             let isSenteCornerBishop = plr == Sente && to == (9, 7)
                 isGoteCornerBishop  = plr == Gote && to == (1, 3)
             in if isSenteCornerBishop || isGoteCornerBishop
                then 900.0
                else 0.0
           _ -> 0.0
       _ -> 0.0


-- ============================================================================
-- 序盤の包括的モース勾配流：駒を前進させる手の網羅（Comprehensive Forward Flow）
-- 歩・銀・桂・角・飛の力強い前進、および戦型コミットメント（攻め筋の一貫性）
-- ============================================================================

-- | 1. 序盤の駒前進勾配流（着手スコア）：駒を前進させる手を網羅的に強力加点
evalComprehensiveAdvancementFlow :: State -> Move -> Double
evalComprehensiveAdvancementFlow st m =
  let plr = turn st
      opp = opponent plr
      curBd = board st
      nextSt = applyMove m st
      nextBd = board nextSt
  in case m of
       NormalMove from to _ ->
         let (fx, fy) = from
             (tx, ty) = to
             isAdvancing = if plr == Sente then ty < fy else ty > fy
         in case Map.lookup from curBd of
              -- A. 歩の前進勾配流（飛車先突き・中央突き・石田流急所・拠点構築）
              Just (Piece p Pawn) | p == plr ->
                let isRookPawnAdvance =
                      if plr == Sente
                      then (from == (2, 7) && to == (2, 6)) || (from == (2, 6) && to == (2, 5)) || (from == (2, 5) && to == (2, 4))
                      else (from == (8, 3) && to == (8, 4)) || (from == (8, 4) && to == (8, 5)) || (from == (8, 5) && to == (8, 6))
                    isCentralPawnAdvance =
                      if plr == Sente
                      then (from == (5, 7) && to == (5, 6)) || (from == (5, 6) && to == (5, 5))
                      else (from == (5, 3) && to == (5, 4)) || (from == (5, 4) && to == (5, 5))
                    isIshidaPawnAdvance =
                      if plr == Sente
                      then (from == (7, 7) && to == (7, 6)) || (from == (7, 6) && to == (7, 5))
                      else (from == (3, 3) && to == (3, 4)) || (from == (3, 4) && to == (3, 5))
                    isSidePawnAdvance =
                      if plr == Sente
                      then (from `elem` [(4, 7), (6, 7), (3, 7)] && isAdvancing)
                      else (from `elem` [(6, 3), (4, 3), (7, 3)] && isAdvancing)
                in if isRookPawnAdvance
                   then (if to == (2, 4) || to == (8, 6) then 1500.0 else (if to == (2, 5) || to == (8, 5) then 1200.0 else 1000.0))
                   else if isCentralPawnAdvance
                   then (if to == (5, 5) then 1300.0 else 1000.0)
                   else if isIshidaPawnAdvance
                   then (if to == (7, 5) || to == (3, 5) then 1300.0 else 1000.0)
                   else if isSidePawnAdvance
                   then 600.0
                   else if isAdvancing
                   then 350.0
                   else 0.0

              -- B. 銀の前進勾配流（棒銀・腰掛け銀・早繰り銀・中央進出）
              Just (Piece p Silver) | p == plr ->
                let isClimbingSilver =
                      if plr == Sente
                      then (fx `elem` [1, 2, 3] && tx `elem` [1, 2, 3] && ty <= 7)
                      else (fx `elem` [7, 8, 9] && tx `elem` [7, 8, 9] && ty >= 3)
                    isCentralSilver =
                      if plr == Sente
                      then to `elem` [(5, 6), (4, 6), (6, 6), (5, 5), (4, 5)]
                      else to `elem` [(5, 4), (6, 4), (4, 4), (5, 5), (6, 5)]
                    isFrontline = if plr == Sente then ty <= 5 else ty >= 5
                in if not isAdvancing then 0.0
                   else if isClimbingSilver then 1800.0 -- 棒銀の力強い進出！
                   else if isCentralSilver  then 1800.0 -- 腰掛け銀・中央厚み進出！
                   else if isFrontline      then 1200.0 -- 前線進出！
                   else 800.0

              -- C. 桂馬の前進勾配流（跳躍・石田流本組）
              Just (Piece p Knight) | p == plr ->
                let isIshidaKnight = (plr == Sente && to == (7, 7)) || (plr == Gote && to == (3, 3))
                    isAttackKnight = if plr == Sente
                                     then to `elem` [(3, 7), (4, 5), (7, 5), (2, 5)]
                                     else to `elem` [(7, 3), (6, 5), (3, 5), (8, 5)]
                in if isIshidaKnight then 1200.0
                   else if isAttackKnight then 1200.0
                   else if isAdvancing then 600.0
                   else 0.0

              -- D. 角の活用・前進勾配流
              Just (Piece p Bishop) | p == plr ->
                let isCornerBishop = (plr == Sente && to == (9, 7)) || (plr == Gote && to == (1, 3))
                    isCenterBishop = if plr == Sente
                                     then to `elem` [(7, 7), (6, 6), (5, 7), (7, 9)]
                                     else to `elem` [(3, 3), (4, 4), (5, 3), (3, 1)]
                in if isCornerBishop then 900.0
                   else if isCenterBishop then 800.0
                   else 300.0

              -- E. 飛車の前進勾配流（浮き飛車・前線突破）
              Just (Piece p Rook) | p == plr ->
                let isFloatingRook =
                      (plr == Sente && (to == (7, 6) || to == (2, 6) || to == (5, 6))) ||
                      (plr == Gote &&  (to == (3, 4) || to == (8, 4) || to == (5, 4)))
                    isVanguardRook = if plr == Sente then ty <= 5 else ty >= 5
                in if isFloatingRook then 3400.0
                   else if isVanguardRook then 1500.0
                   else 0.0
              _ -> 0.0
       _ -> 0.0

-- | 2. 攻め筋の一貫性（Strategic Commitment）：戦型フラフラ乗り換え・振り直し・分裂手の完全根絶
evalStrategicCommitment :: State -> Move -> Double
evalStrategicCommitment st m =
  let plr = turn st
      opp = opponent plr
      curBd = board st
      hist = moveHistory st
      -- 先手の選択した主戦型の判定
      hasPlayedIshida = any (\mvStr -> mvStr == "2h7h" || mvStr == "7f7e") hist
      hasPlayedNakabisha = any (\mvStr -> mvStr == "2h5h" || mvStr == "5g5f") hist
      hasPlayedIbisha = any (\mvStr -> mvStr == "2g2f" || mvStr == "2f2e") hist
  in case m of
       NormalMove from to _ ->
         let (fx, fy) = from
             (tx, ty) = to
             isCapturing = Map.member to curBd
         in case Map.lookup from curBd of
              -- 飛車の振り直し（筋の転換）厳罰
              Just (Piece p Rook) | p == plr ->
                let isSwitchingMode =
                      if plr == Sente
                      then (hasPlayedIshida && tx `notElem` [7]) ||
                           (hasPlayedNakabisha && tx `notElem` [5]) ||
                           (hasPlayedIbisha && tx `notElem` [2])
                      else False
                in if isSwitchingMode && not isCapturing
                   then -5000.0 -- 一度決めた主戦型を放棄して別の筋へ振り直す日和見を完全厳禁！
                   else 0.0

              -- 歩の突きによる戦型の分裂・不整合の厳罰
              Just (Piece p Pawn) | p == plr ->
                let isIbishaPawn = (plr == Sente && from == (2, 7) && to == (2, 6)) ||
                                   (plr == Gote && from == (8, 3) && to == (8, 4))
                    isIshidaPawn = (plr == Sente && from == (7, 6) && to == (7, 5)) ||
                                   (plr == Gote && from == (3, 4) && to == (3, 5))
                    -- 石田流・振飛車を選んだのに、居飛車の2筋の歩を突いて分裂する手
                    isContradictoryAdvance =
                      if plr == Sente
                      then ((hasPlayedIshida || hasPlayedNakabisha) && isIbishaPawn) ||
                           (hasPlayedIbisha && isIshidaPawn)
                      else False
                in if isContradictoryAdvance && not isCapturing
                   then -5000.0 -- 戦型方針と矛盾する分裂手を完全排除！
                   else 0.0
              _ -> 0.0
       _ -> 0.0

-- | 3. 局面評価：全駒の前進ポテンシャルエネルギー（Advancement Potential Energy）
evalComprehensiveAdvancementFormation :: Player -> State -> Double
evalComprehensiveAdvancementFormation p st =
  let bd = board st
      pieces = [ (sq, pt) | (sq, Piece owner pt) <- Map.toList bd, owner == p ]
      scorePiece ((x, y), pt) =
        let adv = if p == Sente then 9 - y else y - 1
        in case pt of
             Pawn ->
               let isAdvancedPawn = if p == Sente then y <= 6 else y >= 4
                   isDeepPawn     = if p == Sente then y <= 5 else y >= 5
               in fromIntegral adv * 30.0 + (if isDeepPawn then 250.0 else (if isAdvancedPawn then 120.0 else 0.0))
             Silver ->
               let isDeepSilver = if p == Sente then y <= 5 else y >= 5
               in fromIntegral adv * 50.0 + (if isDeepSilver then 400.0 else 0.0)
             Knight ->
               fromIntegral adv * 40.0
             Rook ->
               let isFloating = if p == Sente then y <= 6 else y >= 4
               in if isFloating then 300.0 else 0.0
             _ -> 0.0
  in sum (map scorePiece pieces)

-- ============================================================================
-- 居飛車の飛車先受け（Ironclad Rook-File Defense）＆ 居玉防止＆美濃・つの銀中飛車
-- ============================================================================

-- | 相手の飛車先直射に対して、手持ちに歩があるのに歩以外の駒（角・金・銀等）を差し出す大悪手を完全除外
-- ★ 歩で受かるのに大駒や金銀を合駒として打つ手は、自滅的駒損・手損であり絶対禁止！
isFutileInterpositionOnRookFile :: State -> Move -> Bool
isFutileInterpositionOnRookFile st m =
  let plr = turn st
      opp = opponent plr
      bd = board st
      myHand = Map.findWithDefault Map.empty plr (hands st)
      hasPawn = Map.findWithDefault 0 Pawn myHand > 0
  in if not hasPawn
     then False -- 手持ちに歩がない（歩切れ）なら緊急合駒として角や金銀の合駒もやむを得ない
     else case m of
       DropMove pt toSq ->
         let isSenteBreached = plr == Sente && toSq == (8, 7) &&
                               (Map.lookup (8, 6) bd == Just (Piece opp Rook) || Map.lookup (8, 5) bd == Just (Piece opp Rook))
             isGoteBreached  = plr == Gote  && toSq == (2, 3) &&
                               (Map.lookup (2, 4) bd == Just (Piece opp Rook) || Map.lookup (2, 5) bd == Just (Piece opp Rook))
         in (isSenteBreached || isGoteBreached) && pt /= Pawn
       _ -> False

-- | 相手の飛車先突破（8六歩/2四歩の歩突き、または8六飛/2四飛の直射）を放置する致命的手抜き手の完全除外
-- ★ 相手の歩が突き刺さっている時は「同歩」のみを許可
-- ★ 相手の飛車が直射していて手持ちに歩がある時は「歩打ち」のみを許可
isFutileIgnoredRookVanguard :: State -> Move -> Bool
isFutileIgnoredRookVanguard st m =
  let plr = turn st
      opp = opponent plr
      bd = board st
      myHand = Map.findWithDefault Map.empty plr (hands st)
      hasPawn = Map.findWithDefault 0 Pawn myHand > 0
      
      -- A. 相手の歩が飛車先に突き刺さっている（先手: (8, 6)に後手歩、(8, 7)に自歩 / 後手: (2, 4)に先手歩、(2, 3)に自歩）
      sentePawnBreach = plr == Sente && Map.lookup (8, 6) bd == Just (Piece opp Pawn) && Map.lookup (8, 7) bd == Just (Piece Sente Pawn)
      gotePawnBreach  = plr == Gote  && Map.lookup (2, 4) bd == Just (Piece opp Pawn) && Map.lookup (2, 3) bd == Just (Piece Gote Pawn)
      
      -- B. 相手の飛車が直射している（先手: (8, 6)か(8, 5)に後手飛車、(8, 7)が空き / 後手: (2, 4)か(2, 5)に先手飛車、(2, 3)が空き）
      senteRookBreach = plr == Sente && (Map.lookup (8, 6) bd == Just (Piece opp Rook) || Map.lookup (8, 5) bd == Just (Piece opp Rook)) && Map.lookup (8, 7) bd == Nothing
      goteRookBreach  = plr == Gote  && (Map.lookup (2, 4) bd == Just (Piece opp Rook) || Map.lookup (2, 5) bd == Just (Piece opp Rook)) && Map.lookup (2, 3) bd == Nothing
  in if sentePawnBreach
     then case m of
            NormalMove (8, 7) (8, 6) _ -> False -- 8六同歩のみ許可！
            _                          -> True  -- それ以外のすべての手抜き手は完全除外！
     else if gotePawnBreach
     then case m of
            NormalMove (2, 3) (2, 4) _ -> False -- 2四同歩のみ許可！
            _                          -> True  -- それ以外のすべての手抜き手は完全除外！
           else if senteRookBreach && hasPawn
      then case m of
             DropMove Pawn (8, 7) -> False -- 8七歩打のみ許可！
             NormalMove (6, 9) (7, 8) False -> False -- 7八金も許可！
             NormalMove (7, 9) (7, 8) False -> False -- 7八銀も許可！
             _                    -> True  -- それ以外のすべての手抜き手は完全除外！
      else if goteRookBreach && hasPawn
      then case m of
             DropMove Pawn (2, 3) -> False -- 2三歩打のみ許可！
             NormalMove (4, 1) (3, 2) False -> False -- 3二金も許可！（相掛かり二枚竜完封）
             NormalMove (3, 1) (3, 2) False -> False -- 3二金も許可！
             _                    -> True  -- それ以外のすべての手抜き手は完全除外！
      else False

-- | 飛車先の受け（Rook-File Interception Defense）：
-- 1. 相手の飛車先突き（8六歩 / 2四歩）に対する「同歩（Capture Vanguard Pawn）」
-- 2. 飛車直射局面における「8七歩打ち（P*8g）」「2三歩打ち（P*2c）」の絶対的歩受け
-- ★ 迎撃・歩受け放置は即敗北（竜作り被弾）に直結するため、玉囲いをも圧倒する最高優先度(+7500点 / -15000点)を付与
evalRookFileDefenseFlow :: State -> Move -> Double
evalRookFileDefenseFlow st m =
  let plr = turn st
      opp = opponent plr
      curBd = board st
      nextSt = applyMove m st
      nextBd = board nextSt
      myHand = Map.findWithDefault Map.empty plr (hands st)
      hasPawn = Map.findWithDefault 0 Pawn myHand > 0
      
      -- 現在、相手の飛車先歩（8六歩 / 2四歩）が自陣に突き刺さっているか
      oppPawnBreaching =
        if plr == Sente
        then Map.lookup (8, 6) curBd == Just (Piece opp Pawn)
        else Map.lookup (2, 4) curBd == Just (Piece opp Pawn)
        
      -- 現在、相手の飛車（8六飛 / 2四飛）が直射しているか
      oppRookBreaching =
        if plr == Sente
        then (Map.lookup (8, 6) curBd == Just (Piece opp Rook) || Map.lookup (8, 5) curBd == Just (Piece opp Rook)) &&
             Map.lookup (8, 7) curBd /= Just (Piece Sente Pawn)
        else (Map.lookup (2, 4) curBd == Just (Piece opp Rook) || Map.lookup (2, 5) curBd == Just (Piece opp Rook)) &&
             Map.lookup (2, 3) curBd /= Just (Piece Gote Pawn)
  in case m of
       -- A. 相手の飛車先直射に対する「8七歩打ち（P*8g）」「2三歩打ち（P*2c）」
       DropMove pt toSq ->
         let isSente87Drop = plr == Sente && toSq == (8, 7) && oppRookBreaching
             isGote23Drop  = plr == Gote  && toSq == (2, 3) && oppRookBreaching
         in if (isSente87Drop || isGote23Drop)
            then if pt == Pawn
                 then 8500.0 -- ★ 飛車先の直射を止める絶対の歩受け手筋！竜作りを完全阻止！
                 else if hasPawn
                      then -15000.0 -- ★ 歩があるのに角や金銀を打つのは自滅的大悪手！
                      else 500.0   -- 歩がない時のやむを得ない緊急合駒
            else if oppRookBreaching then -10000.0 else 0.0

       -- B. 相手の飛車先歩に対する「同歩（Capture Vanguard Pawn）」
       NormalMove from toSq _ ->
         let isSenteCapture86 = plr == Sente && from == (8, 7) && toSq == (8, 6) && oppPawnBreaching
             isGoteCapture24  = plr == Gote  && from == (2, 3) && toSq == (2, 4) && oppPawnBreaching
         in if isSenteCapture86 || isGoteCapture24
            then 7000.0 -- ★ 相手の飛車先突破を同歩で迎え撃つ絶対の迎撃手筋！
            -- 飛車先が突き刺さっているのに手抜き（玉囲い等）をして放置した場合は超厳罰！
            else if oppPawnBreaching || oppRookBreaching
            then -10000.0 -- 飛車先突破を放置して竜を作られる即敗北手抜きを完全排除！
            else 0.0

-- | 中飛車における美濃囲い＆つの銀（Twin Silvers Central Rook）の形成評価
evalNakabishaCastlingFlow :: State -> Move -> Double
evalNakabishaCastlingFlow st m =
  let plr = turn st
      opp = opponent plr
      curBd = board st
      hist = moveHistory st
      isNakabishaMode = any (\mvStr -> mvStr == "2h5h" || mvStr == "5g5f") hist ||
                        Map.lookup (if plr == Sente then (5, 8) else (5, 2)) curBd == Just (Piece plr Rook)
      -- 相手の飛車先が突き刺さっている緊急事態には玉囲いどころではない（迎撃最優先！）
      oppPawnBreaching =
        if plr == Sente then Map.lookup (8, 6) curBd == Just (Piece opp Pawn)
        else Map.lookup (2, 4) curBd == Just (Piece opp Pawn)
      oppRookBreaching =
        if plr == Sente then (Map.lookup (8, 6) curBd == Just (Piece opp Rook) || Map.lookup (8, 5) curBd == Just (Piece opp Rook)) && Map.lookup (8, 7) curBd == Nothing
        else (Map.lookup (2, 4) curBd == Just (Piece opp Rook) || Map.lookup (2, 5) curBd == Just (Piece opp Rook)) && Map.lookup (2, 3) curBd == Nothing
  in if not isNakabishaMode || oppPawnBreaching || oppRookBreaching
     then 0.0 -- 飛車先突破危機の間は玉囲いボーナスを停止し、迎撃を絶対優先！
     else case m of
       -- 1. 玉の美濃囲い移動（5九 -> 4八 -> 3八 -> 2八）
       NormalMove from toSq _ ->
         case Map.lookup from curBd of
           Just (Piece p King) | p == plr ->
             if plr == Sente
             then if toSq == (4, 8) then 1800.0
                  else if toSq == (3, 8) then 2400.0
                  else if toSq == (2, 8) then 2600.0
                  else 0.0
             else if toSq == (6, 2) then 1800.0
                  else if toSq == (7, 2) then 2400.0
                  else if toSq == (8, 2) then 2600.0
                  else 0.0
           -- 2. つの銀中飛車（Twin Silvers: 4七銀・6七銀への展開）
           Just (Piece p Silver) | p == plr ->
             if plr == Sente
             then if toSq == (4, 7) || toSq == (6, 7) then 2200.0
                  else if toSq == (4, 8) || toSq == (6, 8) then 1600.0
                  else 0.0
             else if toSq == (6, 3) || toSq == (4, 3) then 2200.0
                  else if toSq == (6, 2) || toSq == (4, 2) then 1600.0
                  else 0.0
           _ -> 0.0
       _ -> 0.0

-- | 居玉（Sitting King / Central King Danger）の局面ペナルティ
-- 玉が初期位置（5九 / 5一）に居座っている危険局面を厳罰化
-- ★ 飛車先が突き刺さっている危機局面では玉囲いどころではないため居玉ペナルティを停止（迎撃最優先！）
evalSittingKingPenalty :: Player -> State -> Double
evalSittingKingPenalty p st =
  let bd = board st
      opp = opponent p
      kingSq = findKing p bd
      oppMajorCount = length [ sq | (sq, Piece owner pt) <- Map.toList bd, owner == opp, pt `elem` [Rook, PRook, Bishop, PBishop] ]
      oppPawnBreaching = if p == Sente then Map.lookup (8, 6) bd == Just (Piece opp Pawn) else Map.lookup (2, 4) bd == Just (Piece opp Pawn)
      oppRookBreaching = if p == Sente
                         then (Map.lookup (8, 6) bd == Just (Piece opp Rook) || Map.lookup (8, 5) bd == Just (Piece opp Rook)) && Map.lookup (8, 7) bd /= Just (Piece Sente Pawn)
                         else (Map.lookup (2, 4) bd == Just (Piece opp Rook) || Map.lookup (2, 5) bd == Just (Piece opp Rook)) && Map.lookup (2, 3) bd /= Just (Piece Gote Pawn)
  in if oppPawnBreaching || oppRookBreaching
     then 0.0 -- 飛車先迎撃最優先！玉囲いによる点数の歪みをゼロ化！
     else case kingSq of
       Just (5, 9) | p == Sente ->
         -- 先手居玉：相手の大駒がいるのに5九居玉なら超厳罰！
         -2500.0 - fromIntegral oppMajorCount * 400.0
       Just (5, 1) | p == Gote ->
         -2500.0 - fromIntegral oppMajorCount * 400.0
       -- 4八や6八など囲いへの第一歩を踏み出していれば安全
       _ -> 0.0

-- | 美濃囲い・つの銀中飛車の局面完成度評価
evalMinoAndTsunoGinFormation :: Player -> State -> Double
evalMinoAndTsunoGinFormation p st =
  let bd = board st
      kingSq = findKing p bd
      isNakabisha = Map.lookup (if p == Sente then (5, 8) else (5, 2)) bd == Just (Piece p Rook) ||
                    Map.lookup (if p == Sente then (5, 6) else (5, 4)) bd == Just (Piece p Rook)
  in if not isNakabisha
     then 0.0
     else
       let -- 美濃囲い評価
           minoScore = case kingSq of
             Just (kx, ky) | p == Sente && kx `elem` [2, 3] && ky `elem` [8, 9] -> 2400.0
             Just (kx, ky) | p == Gote  && kx `elem` [7, 8] && ky `elem` [1, 2] -> 2400.0
             Just (4, 8)   | p == Sente -> 1500.0
             Just (6, 2)   | p == Gote  -> 1500.0
             _ -> 0.0
           -- つの銀（4七銀＆6七銀）評価
           tsunoScore =
             if p == Sente
             then (if Map.lookup (4, 7) bd == Just (Piece Sente Silver) then 1200.0 else 0.0) +
                  (if Map.lookup (6, 7) bd == Just (Piece Sente Silver) then 1200.0 else 0.0)
             else (if Map.lookup (6, 3) bd == Just (Piece Gote Silver) then 1200.0 else 0.0) +
                  (if Map.lookup (4, 3) bd == Just (Piece Gote Silver) then 1200.0 else 0.0)
       in minoScore + tsunoScore

-- | 局面評価：飛車先突破・直射被弾の危機ペナルティ
-- 相手飛車が直通していて自陣の歩受け（8七/2三）がされていない局面は、
-- 次の手番で竜を作られて即敗北するため超特大ペナルティ(-10000点)
-- ★ 手番側が手持ちに歩を持っている場合は、この手番で受けられるためペナルティ免除
evalRookVanguardBreachPenalty :: Player -> State -> Double
evalRookVanguardBreachPenalty p st =
  let bd = board st
      opp = opponent p
      myHands = Map.findWithDefault Map.empty p (hands st)
      hasPawnInHand = Map.findWithDefault 0 Pawn myHands > 0
      
      -- 相手の歩が突き刺さっているのに、同歩で取らずに手抜き放置した局面
      isPawnIgnored =
        if p == Sente
        then Map.lookup (8, 6) bd == Just (Piece opp Pawn) && Map.lookup (8, 7) bd == Just (Piece Sente Pawn)
        else Map.lookup (2, 4) bd == Just (Piece opp Pawn) && Map.lookup (2, 3) bd == Just (Piece Gote Pawn)
        
      -- 相手の飛車が直射していて、8七/2三に歩がない無防備局面（歩以外の駒や空マスなら突破状態）
      isRookBreached =
        if p == Sente
        then (Map.lookup (8, 6) bd == Just (Piece opp Rook) || Map.lookup (8, 5) bd == Just (Piece opp Rook)) &&
             Map.lookup (8, 7) bd /= Just (Piece Sente Pawn)
        else (Map.lookup (2, 4) bd == Just (Piece opp Rook) || Map.lookup (2, 5) bd == Just (Piece opp Rook)) &&
             Map.lookup (2, 3) bd /= Just (Piece Gote Pawn)
             
      -- 自分が手番(turn st == p)かつ手持ちに歩があるなら、この手番で歩打ち受けできるため無罰
      canDefendThisTurn = turn st == p && hasPawnInHand
  in if isPawnIgnored then -20000.0
     else if isRookBreached && not canDefendThisTurn then -20000.0
     else 0.0

evalPieceShuffling :: State -> Move -> Double
evalPieceShuffling st m =
  let plr = turn st
      opp = opponent plr
      curBd = board st
      hist = history st
      mHist = moveHistory st
      nextSt = applyMove m st
      nextBd = board nextSt
      nextKey = positionKey nextSt
      
      -- 自玉が王手されている時の回避手はペナルティ対象外
      inCheck = isKingUnderAttack plr curBd
      
  in if inCheck
     then 0.0
     else
       let
         -- 1. 同一局面リピート（千日手未遂・Shuffling）の段階的ペナルティ
         repeatCount = Map.findWithDefault 0 nextKey hist
         repeatPen = case repeatCount of
           1 -> -800.0   -- 2回目の出現：明らかな手待ち・千日手未遂に強いペナルティ
           2 -> -3500.0  -- 3回目の出現：直ちに千日手になるため超特大ペナルティ
           _ -> if repeatCount >= 3 then -10000.0 else 0.0
         
         -- 2. 直前の自分の手（2手前）からの直接逆戻り（Immediate Oscillation）検知
         reversalPen = case reverse mHist of
           (_oppMv : myLastMvStr : _) ->
             case (m, parseMove myLastMvStr) of
               (NormalMove curFrom curTo _, NormalMove prevFrom prevTo _) ->
                 if curFrom == prevTo && curTo == prevFrom
                 then
                   let isTargetUnderThreat = not (null (getPiecesCovering opp curFrom curBd))
                       isCapture = Map.member curTo curBd
                       pieceAtFrom = Map.lookup curFrom curBd
                       isRookOrGold = case pieceAtFrom of
                         Just (Piece _ pt) -> pt `elem` [Rook, PRook, Gold, PPawn, PSilver, PKnight, PLance]
                         Nothing           -> False
                       isKing = case pieceAtFrom of
                         Just (Piece _ King) -> True
                         _                   -> False
                   in if isTargetUnderThreat || isCapture
                      then 0.0
                      else if isKing
                           then -3500.0 -- 玉の無意味なうろうろ往復移動には超特大ペナルティ！
                           else if isRookOrGold
                           then -2500.0 -- 飛車・金の無意味な往復移動（うろうろ）には特大ペナルティ！
                           else -1500.0 -- 一般駒の無意味な往復手損ペナルティ
                 else 0.0
               _ -> 0.0
           _ -> 0.0
         
         -- 2.5 玉の彷徨い（Wandering King）防止と囲い入城（Castle Progress）ボーナス
         kingMoveEval = case m of
           NormalMove from to _ ->
             case Map.lookup from curBd of
               Just (Piece p King) | p == plr ->
                 let isMovingToCenter = snd to == 5 || (plr == Sente && snd to == 6) || (plr == Gote && snd to == 4)
                     wanderingPen = if isMovingToCenter then -2000.0 else 0.0
                     
                     -- 囲いの定位置（美濃・矢倉・雁木・エルモ・穴熊）
                     castleSquares = if plr == Sente
                                     then [(7, 8), (8, 8), (7, 9), (6, 8), (8, 9)]
                                     else [(3, 2), (2, 2), (3, 1), (4, 2), (2, 1)]
                     isEnteringCastle = to `elem` castleSquares
                     castleBonus = if isEnteringCastle then 450.0 else 0.0
                 in wanderingPen + castleBonus
               _ -> 0.0
           _ -> 0.0
         
         wanderingGoldPen = case m of
           NormalMove from to _ ->
             case Map.lookup from curBd of
               Just (Piece p Gold) | p == plr ->
                 let curKing = findKing plr curBd
                     oppKing = findKing opp curBd
                     isCapturing = Map.member to curBd
                     isNearOppKing = case oppKing of
                       Just (ekx, eky) -> max (abs (fst to - ekx)) (abs (snd to - eky)) <= 2
                       Nothing         -> False
                     isHomeSquare = if plr == Sente
                                    then to == (4, 9) || to == (6, 9)
                                    else to == (6, 1) || to == (4, 1)
                     homePen = if isHomeSquare then -5000.0 else 0.0
                 in if isCapturing || isNearOppKing
                    then 0.0
                    else
                      let distCur = case curKing of Just (kx, ky) -> abs (fst from - kx) + abs (snd from - ky); Nothing -> 0
                          distNext = case curKing of Just (kx, ky) -> abs (fst to - kx) + abs (snd to - ky); Nothing -> 0
                          movingAwayPen = if distNext > distCur && distNext > 2 then -600.0 else 0.0
                          isMidRank = snd to == 5 || (plr == Sente && snd to == 6) || (plr == Gote && snd to == 4)
                          midRankPen = if isMidRank then -500.0 else 0.0
                      in homePen + movingAwayPen + midRankPen
               _ -> 0.0
           _ -> 0.0

         -- 4. 飛車の振り直し・筋変更・うろうろ手損の完全根絶（Anti-Reswinging & Anti-Wandering）
         aimlessRookPen = case m of
           NormalMove from to promo ->
             case Map.lookup from curBd of
               Just (Piece p Rook) | p == plr ->
                 let isCapturing = Map.member to curBd
                     isCheck = isKingUnderAttack opp nextBd
                     isPromo = promo
                     (fx, fy) = from
                     (tx, ty) = to
                     -- 正当な振飛車・浮き飛車手筋：
                     -- 石田流: 7八飛, 7六浮き飛車 (後手 3二飛, 3四浮き飛車)
                     -- 中飛車: 5八飛, 5六浮き飛車 (後手 5二飛, 5四浮き飛車)
                     -- 四間飛車: 6八飛 (後手 4二飛)
                     -- 居飛車浮き飛車: 2八飛から2六飛
                     isLegitOpeningRook =
                       (plr == Sente && ((from == (2, 8) && to `elem` [(7, 8), (5, 8), (6, 8), (2, 6)]) ||
                                         (from == (7, 8) && to == (7, 6)) ||
                                         (from == (5, 8) && to == (5, 6)))) ||
                       (plr == Gote &&  ((from == (8, 2) && to `elem` [(3, 2), (5, 2), (4, 2), (8, 4)]) ||
                                         (from == (3, 2) && to == (3, 4)) ||
                                         (from == (5, 2) && to == (5, 4))))
                     
                     -- 振り直し（Re-swinging）：一度初期位置(2八/8二)から離れた飛車が、別の筋に再度横移動する手損
                     isReSwinging = (plr == Sente && from /= (2, 8) && fx /= tx && not (from == (7, 8) && to == (7, 6)) && not (from == (5, 8) && to == (5, 6))) ||
                                    (plr == Gote &&  from /= (8, 2) && fx /= tx && not (from == (3, 2) && to == (3, 4)) && not (from == (5, 2) && to == (5, 4)))
                     
                     -- 飛車の無目的後退（ただ下がる）
                     isPointlessRetreat = fx == tx && (plr == Sente && ty > fy || plr == Gote && ty < fy)
                     -- 目的のない自陣内の横移動
                     isAimlessHorizontal = fx /= tx && not isLegitOpeningRook
                 in if isCapturing || isCheck || isPromo
                    then 0.0
                    else if isReSwinging
                    then -5000.0 -- 一度振った飛車の振り直し・筋変更は超特大ペナルティ！
                    else if isAimlessHorizontal
                    then -4500.0 -- 目的のない飛車の自陣横移動・手損に厳罰！
                    else if isPointlessRetreat
                    then -3500.0 -- 飛車の無駄な自陣後退に厳罰！
                    else if isLegitOpeningRook
                    then 0.0
                    else -1500.0
               _ -> 0.0
           _ -> 0.0

                in repeatPen + reversalPen + wanderingGoldPen + aimlessRookPen + kingMoveEval

-- | プロ棋戦の手筋に基づく「受けの筋（Defensive Techniques）」の評価
-- 1. 自陣への歩打ち受け（底歩、中合い、飛車先交換後の歩受け P*2c, P*8g 等）
-- 2. 金銀の引き受け・玉との連結（「金は引く手に好手あり」、玉に密着する守備）
-- 3. 相手の攻撃線（射線・成込み）を遮断する合駒・受け
-- 4. 自陣の角打ち隙（両取りの急所）を消す手筋
evalDefensiveTechnique :: State -> Move -> Double
evalDefensiveTechnique st m =
  let plr = turn st
      opp = opponent plr
      curBd = board st
      nextSt = applyMove m st
      nextBd = board nextSt
      
      curKingSq = findKing plr curBd
      nextKingSq = findKing plr nextBd
      
      -- 1. 歩打ちによる受け（Pawn Drop Defense）
      pawnDropDefenseScore = case m of
        DropMove Pawn (tx, ty) ->
          let isInMyCamp = if plr == Sente then ty >= 7 else ty <= 3
              oppAttackers = getPiecesCovering opp (tx, ty) curBd
              hasEnemyRanger = any (\(_, Piece _ opt) -> opt `elem` [Rook, PRook, Bishop, PBishop, Lance]) oppAttackers
              isRookHeadPawn = (plr == Gote && (tx, ty) == (2, 3)) || (plr == Sente && (tx, ty) == (8, 7))
          in if isRookHeadPawn then 500.0
             else if isInMyCamp && hasEnemyRanger then 420.0
             else if isInMyCamp then 180.0
             else 0.0
        _ -> 0.0
        
      -- 2. 金銀の引き受け・玉との連結（Gold/Silver Solidification）
      -- ★ 厳重注意：金が理由なく初期位置（先手4九・6九 / 後手6一・4一）に戻る手（Home Retreat Blunder）は、
      --   陣形破壊・コビン開放・角打ち被弾の主因であり、絶対にボーナスを与えず特大ペナルティを科す！
      solidDefenseScore = case m of
        NormalMove from to _ ->
          case Map.lookup from curBd of
            Just (Piece p pt) | p == plr && pt `elem` [Gold, Silver] ->
              let isRetreat = if plr == Sente then snd to > snd from else snd to < snd from
                  distNext = case nextKingSq of
                    Just (kx, ky) -> abs (fst to - kx) + abs (snd to - ky)
                    Nothing       -> 99
                  distCur = case curKingSq of
                    Just (kx, ky) -> abs (fst from - kx) + abs (snd from - ky)
                    Nothing       -> 99
                  isClosingToKing = distNext < distCur || (distNext <= 2 && distCur <= 2)
                  
                  -- 金の初期位置への戻り判定 (Home Retreat Blunder)
                  isGold = pt == Gold
                  isHomeSquare = if plr == Sente
                                 then to == (4, 9) || to == (6, 9)
                                 else to == (6, 1) || to == (4, 1)
                  isCapture = Map.member to curBd
                  inCheckNow = isKingUnderAttack plr curBd
                  
                  -- 中飛車陣形における要石（Keystone）の放棄判定
                  -- 5八, 4八, 6八, 5七, 4七, 6七 の金が1段目に後退する手を厳禁
                  isAbandoningCentralKeystone = 
                    if plr == Sente
                    then isGold && snd from <= 8 && snd to == 9
                    else isGold && snd from >= 2 && snd to == 1
                    
                  homeRetreatPen =
                    if isGold && isHomeSquare && not isCapture && not inCheckNow
                    then -6000.0 -- 金が元の位置に戻る自滅手には特大ペナルティ！
                    else if isAbandoningCentralKeystone && not isCapture && not inCheckNow
                    then -5000.0 -- 要石の金を無意味に1段目に引く手損・陣形破壊ペナルティ！
                    else 0.0
                    
                  defendsFriendly = any (\(sq, Piece own _) -> own == plr && isSquareUnderAttack opp sq curBd && isSquareUnderAttack plr sq nextBd) (Map.toList nextBd)
                  defendBonus = if defendsFriendly then 280.0 else 0.0
                  -- 金銀の後退ボーナスは完全撤廃（金の無駄戻りの元凶を根絶）
                  retreatBonus = 0.0
              in homeRetreatPen + retreatBonus + defendBonus
            _ -> 0.0
        _ -> 0.0
        
      -- 3. 自陣の角打ち隙（両取り隙）を消す受け
      antiForkDefenseScore =
        case curKingSq of
          Just (kx, ky) ->
            let toSq = case m of NormalMove _ t _ -> t; DropMove _ t -> t
                isDefendingRear = if plr == Sente then snd toSq >= 8 else snd toSq <= 2
            in if isDefendingRear then 180.0 else 0.0
          Nothing -> 0.0
          
      -- 4. ★ 自陣全域（特に中飛車のコビン・玉頭・飛車横）への角打ち・馬作り被弾の完全防止
      --    相手が持ち駒に角を持っている場合、自らの手によって角打ちの隙（コビン）を開放した場合は超厳罰（-8000点）！
      antiBishopDropAndKobinDefenseScore =
        let oppHand = Map.findWithDefault Map.empty opp (hands st)
            hasOppBishopInHand = Map.findWithDefault 0 Bishop oppHand > 0
            
            myCampY = if plr == Sente then [7, 8, 9] else [1, 2, 3]
            campSquares = [ (x, y) | x <- [1..9], y <- myCampY ]
            
            isDangerousBishopDrop bd sq =
              not (Map.member sq bd) &&
              let myDefenders = getPiecesCovering plr sq bd
                  isProtected = not (null myDefenders)
                  
                  isNearMyKing = case (if plr == Sente then nextKingSq else curKingSq) of
                    Just (kx, ky) -> max (abs (fst sq - kx)) (abs (snd sq - ky)) <= 2
                    Nothing       -> False
                    
                  isCentralKeystone = if plr == Sente
                                      then sq `elem` [(3,9), (4,9), (5,8), (6,9), (7,9), (4,8), (6,8), (5,7)]
                                      else sq `elem` [(7,1), (6,1), (5,2), (4,1), (3,1), (6,2), (4,2), (5,3)]
                                      
                  testBdWithBishop = Map.insert sq (Piece opp Bishop) bd
                  threatenedSquares = [ tsq | (tsq, Piece p pt) <- Map.toList testBdWithBishop
                                            , p == plr
                                            , pt `elem` [King, Rook, PRook, Gold, Silver]
                                            , canPieceReachTarget sq (Piece opp Bishop) tsq testBdWithBishop ]
                  isForkingHighValue = length threatenedSquares >= 2 || any (\tsq -> Map.lookup tsq bd == Just (Piece plr King)) threatenedSquares
              in not isProtected && (isNearMyKing || isCentralKeystone || isForkingHighValue)

            curDangerousCount = length (filter (isDangerousBishopDrop curBd) campSquares)
            nextDangerousCount = length (filter (isDangerousBishopDrop nextBd) campSquares)
            
            kobinDiff = nextDangerousCount - curDangerousCount
            kobinScore =
              if kobinDiff > 0
              then -8000.0 * fromIntegral kobinDiff
              else if kobinDiff < 0
              then 2200.0 * fromIntegral (- kobinDiff)
              else 0.0
              
            rookRetreatBonus = case m of
              NormalMove from to _ ->
                case Map.lookup from curBd of
                  Just (Piece p Rook) | p == plr ->
                    let isUnderAttack = isSquareUnderAttack opp from curBd
                        isRetreatToHome = if plr == Sente then to == (2, 8) else to == (8, 2)
                    in if isUnderAttack && isRetreatToHome then 1200.0
                       else if isRetreatToHome then 600.0
                       else 0.0
                  _ -> 0.0
              _ -> 0.0
        in if hasOppBishopInHand
           then kobinScore + rookRetreatBonus
           else rookRetreatBonus
      
      -- 5. ★ 4枚の攻めを受けきる守り（金、銀、桂、香の連携受け・底香・底歩）
      fourPieceDefenseCoverScore =
        let toSq = case m of NormalMove _ t _ -> t; DropMove _ t -> t
            ptMoved = case m of
              NormalMove f _ _ -> case Map.lookup f curBd of Just (Piece _ pt) -> pt; Nothing -> Pawn
              DropMove pt _    -> pt
            isInMyCamp = if plr == Sente then snd toSq >= 7 else snd toSq <= 3
            isGuardPiece = ptMoved `elem` [Gold, Silver, Knight, Lance, Pawn]
            isNearKing = case nextKingSq of
              Just (kx, ky) -> abs (fst toSq - kx) <= 3 && abs (snd toSq - ky) <= 3
              Nothing       -> False
            isCoveringAttackedPiece = any (\(sq, Piece own _) -> own == plr && isSquareUnderAttack opp sq curBd && isSquareUnderAttack plr sq nextBd) (Map.toList nextBd)
            oppAttackersOnTo = getPiecesCovering opp toSq nextBd
            myDefendersOnTo = getPiecesCovering plr toSq nextBd
            isInterposingOrSolidifying = not (null oppAttackersOnTo) && not (null myDefendersOnTo)
        in if isGuardPiece && (isInMyCamp || isNearKing)
           then if isInterposingOrSolidifying then 450.0
                else if isCoveringAttackedPiece then 350.0
                else if ptMoved == Lance && (snd toSq == 9 || snd toSq == 1) then 300.0
                else 100.0
           else 0.0
          
  in pawnDropDefenseScore + solidDefenseScore + antiForkDefenseScore + antiBishopDropAndKobinDefenseScore + fourPieceDefenseCoverScore

-- | 厚み（Thick Formations）と位取り（Dominance / Territorial Control）、囲いと駒組みの評価
-- 1. 中央（5筋・4筋・6筋）の位取り（歩の前進、相手を圧迫）
-- 2. 歩越し銀（銀が歩の上に前進して厚みを構築）
-- 3. 金銀のスクラム・連結（金と銀、銀と銀が互いに支え合って鉄壁を形成）
-- 4. 堅陣囲い（玉の周囲に金銀が連結配置される美しい駒組み）
evalThicknessAndDominance :: State -> Move -> Double
evalThicknessAndDominance st m =
  let plr = turn st
      opp = opponent plr
      curBd = board st
      nextSt = applyMove m st
      nextBd = board nextSt
      
      -- 1. 中央および要所の位取り（Territorial Control）
      territoryScore = case m of
        NormalMove _ (tx, ty) _ ->
          let isVanguardPawn = case Map.lookup (tx, ty) nextBd of
                Just (Piece p Pawn) -> p == plr
                _                   -> False
              isCenterRank = if plr == Sente
                             then (tx == 5 && ty == 5) || (tx == 5 && ty == 6) || (tx `elem` [4, 6] && ty == 6)
                             else (tx == 5 && ty == 5) || (tx == 5 && ty == 4) || (tx `elem` [4, 6] && ty == 4)
              isDeepRank   = if plr == Sente then (tx == 5 && ty == 5) else (tx == 5 && ty == 5)
          in if isVanguardPawn && isDeepRank then 380.0
             else if isVanguardPawn && isCenterRank then 260.0
             else 0.0
        _ -> 0.0
        
      -- 2. 歩越し銀（Silver vanguard building thickness）
      silverVanguardScore = case m of
        NormalMove _ (tx, ty) _ ->
          case Map.lookup (tx, ty) nextBd of
            Just (Piece p Silver) | p == plr ->
              let pawnBelow = if plr == Sente then (tx, ty + 1) else (tx, ty - 1)
                  hasPawnBelow = Map.lookup pawnBelow nextBd == Just (Piece plr Pawn)
                  isForwardRank = if plr == Sente then ty <= 6 else ty >= 4
              in if hasPawnBelow && isForwardRank then 320.0 else 0.0
            _ -> 0.0
        _ -> 0.0
        
      -- 3. 金銀の連結・スクラム（Gold-Silver Connection）
      scrumScore = case m of
        NormalMove _ to _ ->
          case Map.lookup to nextBd of
            Just (Piece p pt) | p == plr && pt `elem` [Gold, Silver] ->
              let (tx, ty) = to
                  neighbors = [ (tx + dx, ty + dy) | dx <- [-1..1], dy <- [-1..1], (dx, dy) /= (0, 0) ]
                  adjacentGenerals = length [ sq | sq <- neighbors
                                                 , case Map.lookup sq nextBd of
                                                     Just (Piece p2 pt2) -> p2 == plr && pt2 `elem` [Gold, Silver]
                                                     _                   -> False ]
              in fromIntegral adjacentGenerals * 150.0
            _ -> 0.0
        _ -> 0.0
        
      -- 4. 囲いの完成度・玉との連結度（Castle Formation & Coordination）
      curKingSq = findKing plr curBd
      nextKingSq = findKing plr nextBd
      castleScore = case nextKingSq of
        Just (kx, ky) ->
          let neighbors = [ (kx + dx, ky + dy) | dx <- [-1..1], dy <- [-1..1], (dx, dy) /= (0, 0) ]
              protectingGenerals = length [ sq | sq <- neighbors
                                               , case Map.lookup sq nextBd of
                                                   Just (Piece p pt) -> p == plr && pt `elem` [Gold, Silver]
                                                   _                 -> False ]
          in fromIntegral protectingGenerals * 160.0
        Nothing -> 0.0
        
  in territoryScore + silverVanguardScore + scrumScore + castleScore

calcTimeLimitMicros :: Player -> [String] -> Int
calcTimeLimitMicros ply tokens =
  let byo = case elemIndex "byoyomi" tokens of
        Just idx | idx + 1 < length tokens -> readMaybe (tokens !! (idx + 1))
        _ -> Nothing
      movetime = case elemIndex "movetime" tokens of
        Just idx | idx + 1 < length tokens -> readMaybe (tokens !! (idx + 1))
        _ -> Nothing
      btime = case elemIndex "btime" tokens of
        Just idx | idx + 1 < length tokens -> readMaybe (tokens !! (idx + 1))
        _ -> Nothing
      wtime = case elemIndex "wtime" tokens of
        Just idx | idx + 1 < length tokens -> readMaybe (tokens !! (idx + 1))
        _ -> Nothing
      binc = case elemIndex "binc" tokens of
        Just idx | idx + 1 < length tokens -> readMaybe (tokens !! (idx + 1))
        _ -> Nothing
      winc = case elemIndex "winc" tokens of
        Just idx | idx + 1 < length tokens -> readMaybe (tokens !! (idx + 1))
        _ -> Nothing
      
      (myTime, myInc) = case ply of
        Sente -> (btime, binc)
        Gote  -> (wtime, winc)
      
      -- 通信・GUIバッファの安全マージン（150ms）
      safetyMargin = 150
      
      -- 思考上限ミリ秒
      timeMs = case (byo, movetime, myTime, myInc) of
        -- 1. byoyomi 指定がある場合: byoyomi の秒数を上限とする (0の場合は持ち時間制へフォールバック)
        (Just b, _, _, _) | b > 0 -> max 100 (b - safetyMargin)
        -- 2. movetime 指定がある場合: movetime を上限とする
        (_, Just m, _, _) -> max 100 (m - safetyMargin)
        -- 3. フィッシャールール (inc 指定あり)
        (_, _, Just t, Just inc) -> max 100 (min (t `div` 15 + inc) (t + inc - safetyMargin))
        -- 4. 持ち時間制 (残り時間から算出)
        (_, _, Just t, _) -> max 100 (t `div` 20)
        -- 5. 指定なし (デフォルト1秒秒読み相当: 850ms)
        _                 -> 850
  in timeMs * 1000

-- | 反復深化探索 (byoyomi を上限とし、タイムアウトで打ち切り)
searchBestMoveIterativeWithTimeout :: MidgameWeights -> Int -> State -> IO (Either String Move, State)
searchBestMoveIterativeWithTimeout weights timeLimitMicros state = do
  let inCheck = isKingUnderAttack (turn state) (board state)
      moves = generateMoves state
      f5FilteredMoves = f5SyzygyFilter state moves
      (_sennichiteMoves, safeMoves) = 
        partition (\m -> 
          let nextState = applyMove m state
          in isSennichite (positionKey nextState) (history nextState)
        ) f5FilteredMoves
      -- ★ 王手されている局面では一切の除外を行わずすべての王手回避手を検討する
      nonKakutoMoves = if inCheck
                       then safeMoves
                       else filter (\m -> not (isPushingKakutoPawn state m) && not (isFutileLanceLift state m) && not (isFutileInterpositionOnRookFile state m) && not (isFutileIgnoredRookVanguard state m) && not (isIgnoringMajorCapturable state m)) safeMoves
      effectiveMoves = if null nonKakutoMoves then safeMoves else nonKakutoMoves

      -- ★ QEGTB（商空間エンドゲームテーブル）の王手無視・自殺手判定の完全防止：
      --   自玉が現在王手されている場合、またはmateMoveが自玉を王手から救っていない場合は、
      --   QEGTBの詰み手であっても絶対に採用せず、王手回避・正規探索に委ねる！
      validEgtb = case lookupQuotientTablebase state of
        Just (dtm, mateMove) ->
          let safeMvs = f5SyzygyFilter state [mateMove]
          in if inCheck
             then Nothing
             else case safeMvs of
                    [safeM] | safeM `elem` effectiveMoves -> Just (dtm, safeM)
                    _                                     -> Nothing
        Nothing -> Nothing

      -- 1. 最優先：定跡・スーパーハイウェイ（検証済み必勝完全棋譜）を照会
      maybeBook = lookupBookMove (moveHistory state) state

  case maybeBook of
    Just bookMove -> do
      putStrLn $ "info string book hit pv " ++ showMove bookMove
      hFlush stdout
      return (Right bookMove, state)
    Nothing ->
      case validEgtb of
        Just (dtm, mateMove) -> do
          putStrLn $ "info string quotient egtb hit dtm " ++ show dtm ++ " score mate " ++ show dtm ++ " pv " ++ showMove mateMove
          hFlush stdout
          return (Right mateMove, state)
        Nothing -> do
          -- 3. 定跡外または定跡完了後は、反復深化α-β探索（Garsideキャッシュ + F5フィルター + タダ捨て防止 + 静止探索）
          if null f5FilteredMoves
            then return (Left "resign", state)
            else if null effectiveMoves
              then return (Left "draw", state)
              else
                case Map.lookup (positionKey state) (cache state) of
                  Just (_score, mv) | mv `elem` effectiveMoves -> do
                    putStrLn $ "info string hash hit pv " ++ showMove mv
                    hFlush stdout
                    return (Right mv, state)
                  _ -> do
                     -- 初期フォールバックとして合法かつ安全な最善手候補を設定
                     let fallbackMove = case effectiveMoves of (m:_) -> m; [] -> error "no effective moves"
                     bestRef <- newIORef (0.0, fallbackMove, [fallbackMove])
                 
                     -- タイムアウト付き探索 (byoyomi に応じて depth 1..36 まで深掘り探索)
                     _ <- timeout timeLimitMicros $ do
                       let runIDS d
                             | d > 36 = return ()
                             | otherwise = do
                                 let (score, pv) = searchAlphaBeta weights d (-99999.0) 99999.0 state
                                 hFlush stdout
                                 case pv of
                                   (mv:_) | mv `elem` effectiveMoves -> do
                                     _ <- evaluate (score `seq` mv `seq` ())
                                     writeIORef bestRef (score, mv, pv)
                                     let pvStr = unwords (map showMove pv)
                                     putStrLn $ "info depth " ++ show d ++ " score cp " ++ show (round score :: Int) ++ " pv " ++ pvStr
                                     hFlush stdout
                                     if abs score >= 9000.0
                                       then return () -- 詰みを発見した場合は直ちに停止
                                       else runIDS (d + 1)
                                   _ -> return ()
                       runIDS 1
                 
                     -- タイムアウトした場合でも、前回までに探索した最深の最善手を取得
                     (bestScore, rawBestMove, _finalPv) <- readIORef bestRef
                     let bestMove = if rawBestMove `elem` f5FilteredMoves
                                    then rawBestMove
                                    else fallbackMove
                         newCache = Map.insert (positionKey state) (bestScore, bestMove) (cache state)
                     return (Right bestMove, state { cache = newCache })

-- 後方互換用：純粋探索
searchBestMoveWithCache :: MidgameWeights -> State -> (Either String Move, State)
searchBestMoveWithCache weights state =
  let inCheck = isKingUnderAttack (turn state) (board state)
      maybeBook = lookupBookMove (moveHistory state) state
  in case maybeBook of
    Just bookMove ->
      (Right bookMove, state)
    Nothing ->
      let moves = generateMoves state
          f5FilteredMoves = f5SyzygyFilter state moves
          (_sennichiteMoves, safeMoves) = 
            partition (\m -> 
              let nextState = applyMove m state
              in isSennichite (positionKey nextState) (history nextState)
            ) f5FilteredMoves
          nonKakutoMoves = if inCheck
                           then safeMoves
                           else filter (\m -> not (isPushingKakutoPawn state m) && not (isFutileLanceLift state m) && not (isFutileInterpositionOnRookFile state m) && not (isFutileIgnoredRookVanguard state m) && not (isIgnoringMajorCapturable state m)) safeMoves
          effectiveMoves = if null nonKakutoMoves then safeMoves else nonKakutoMoves
      in if null f5FilteredMoves
         then (Left "resign", state)
         else if null effectiveMoves
           then (Left "draw", state)
           else
             case Map.lookup (positionKey state) (cache state) of
               Just (_score, mv) | mv `elem` effectiveMoves -> (Right mv, state)
               _ ->
                  let (bestScore, pv) = searchAlphaBeta weights 5 (-99999.0) 99999.0 state
                  in case pv of
                       (bestMove:_) | bestMove `elem` f5FilteredMoves ->
                         let newCache = Map.insert (positionKey state) (bestScore, bestMove) (cache state)
                         in (Right bestMove, state { cache = newCache })
                       _ ->
                         case effectiveMoves of
                           (m:_) -> (Right m, state)
                           []    -> (Left "resign", state)

-- ============================================================================
-- 9. USIメインループ
-- ============================================================================

main :: IO ()
main = do
  hSetBuffering stdin LineBuffering
  hSetBuffering stdout LineBuffering
  weights <- loadMidgameWeights
  usiLoop weights initState

usiLoop :: MidgameWeights -> State -> IO ()
usiLoop weights currentState = do
  line <- getLine
  let tokens = words line
  case tokens of
    [] -> usiLoop weights currentState
    (cmd:_) -> case cmd of
      "usi" -> do
        putStrLn "id name ShogiMorseEngine_Haskell_with_F5_Garside_and_Sennichite"
        putStrLn "id author Shogi_Topology_Project"
        putStrLn "usiok"
        hFlush stdout
        usiLoop weights currentState
      
      "isready" -> do
        putStrLn "readyok"
        hFlush stdout
        usiLoop weights currentState
      
      "usinewgame" -> do
        w <- loadMidgameWeights
        usiLoop w initState { cache = Map.empty }
      
      "position" -> do
        let movesTokens = case elemIndex "moves" tokens of
              Just idx -> drop (idx + 1) tokens
              Nothing  -> []
            baseTokens = case elemIndex "moves" tokens of
              Just idx -> take idx tokens
              Nothing  -> tokens
            baseState = case drop 1 baseTokens of
              ("startpos":_) -> initState
              ("sfen":sfenParts) -> parseSfen sfenParts
              _ -> initState
            finalState = foldl' (\st mvStr -> applyMove (parseMove mvStr) st) baseState movesTokens
        usiLoop weights finalState { cache = cache currentState, moveHistory = movesTokens }
      
      "go" -> do
        let timeLimitMicros = calcTimeLimitMicros (turn currentState) (drop 1 tokens)
        (res, nextState) <- searchBestMoveIterativeWithTimeout weights timeLimitMicros currentState
        case res of
          Left "draw" -> do
            putStrLn "bestmove draw"
            hFlush stdout
            usiLoop weights nextState
          Left _ -> do
            putStrLn "bestmove resign"
            hFlush stdout
            usiLoop weights nextState
          Right best -> do
            putStrLn $ "bestmove " ++ showMove best
            hFlush stdout
            usiLoop weights nextState
      
      "eval" -> do
        let p = turn currentState
            opp = opponent p
            bd = board currentState
            myDanger = evalMorsePotential p bd
            enemyDanger = evalMorsePotential opp bd
            morse = (enemyDanger - myDanger) * wMorseDanger weights
            mat = evalMaterial p currentState * wMaterial weights
            hang = evalHangingPieces p currentState
            atk = (evalMidgameAttack p currentState - evalMidgameAttack opp currentState) * wAttack weights
            defn = (evalMidgameDefense p currentState - evalMidgameDefense opp currentState) * wDefense weights
            kakuto = evalKakutoKeitoDefense p currentState * wKakuto weights
            ishida = evalSilverAdvanceAndIshidaFormation p currentState - evalSilverAdvanceAndIshidaFormation opp currentState
            ctrl = evalPieceControl p currentState * wPieceControl weights
            loose = evalLoosePieces p currentState * wLoosePenalty weights
            tempo = evalTempoLoss p currentState * wTempoLoss weights
            goldKing = evalGoldKingCoordination p currentState * wGoldKingCoord weights
            dtm = (evalDistanceToMate p currentState - evalDistanceToMate opp currentState) * wDistanceToMate weights
            numAssault = (evalNumericalAssault p currentState - evalNumericalAssault opp currentState) * wNumericalAssault weights
            bdrop = evalBishopDropVulnerability p currentState - evalBishopDropVulnerability opp currentState
            potRay = evalPotentialRayAttack p currentState * wPotentialRays weights
            total = evaluateState weights p currentState
        putStrLn $ "info string eval total=" ++ show total ++ " morse=" ++ show morse ++ " kakuto=" ++ show kakuto ++ " goldKing=" ++ show goldKing ++ " dtm=" ++ show dtm ++ " numAssault=" ++ show numAssault ++ " ishida=" ++ show ishida
        hFlush stdout
        usiLoop weights currentState

      "quit" -> do
        exitSuccess
      
      _ -> usiLoop weights currentState
